16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "postcode")
59	    private String postcode;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    private String email;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "registration_date")
73	    private LocalDate registrationDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @Column(name = "deleted", nullable = false)
94	    private boolean deleted;
95	
96	    /**
97	     * Whether this owner was knowingly created into a shared household (the request declared shared
98	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
99	     * never persisted.
100	     */
101	    @Transient
102	    private boolean declaredHouseholdMember;
103	
104	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
105	    private Set<Pet> pets;
106	
107	    /**
108	     * Resolve the registration date at creation time: default it to the server's
109	     * current date when none was supplied, and roll a weekend date forward to the
110	     * next business day so every value derived from it (such as the membership
111	     * number's year segment) uses the adjusted date.
112	     */
113	    @PrePersist
114	    private void resolveRegistrationDate() {
115	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
116	    }
117	
118	    public String getTitle() {
119	        return this.title;
120	    }
121	
122	    public void setTitle(String title) {
123	        this.title = title;
124	    }
125	
126	    /**
127	     * The owner's salutation: the {@link #title} followed by a space and the
128	     * {@linkplain #getLastName() last name} (e.g. {@code "DR Who"}), or just the
129	     * last name when no title is on file.
130	     */
131	    public String getSalutation() {
132	        if (this.title == null || this.title.isEmpty()) {
133	            return getLastName();
134	        }
135	        return this.title + " " + getLastName();
136	    }
137	
138	    public String getAddress() {
139	        return this.address;
140	    }
141	
142	    public void setAddress(String address) {
143	        this.address = address;
144	    }
145	
146	    public String getAddressLine1() {
147	        return this.addressLine1;
148	    }
149	
150	    public void setAddressLine1(String addressLine1) {
151	        this.addressLine1 = addressLine1;
152	    }
153	
154	    public String getAddressLine2() {
155	        return this.addressLine2;
156	    }
157	
158	    public void setAddressLine2(String addressLine2) {
159	        this.addressLine2 = addressLine2;
160	    }
161	
162	    public String getCity() {
163	        return this.city;
164	    }
165	
166	    public void setCity(String city) {
167	        this.city = city;
168	    }
169	
170	    public String getPostcode() {
171	        return this.postcode;
172	    }
173	
174	    public void setPostcode(String postcode) {
175	        this.postcode = postcode;
176	    }
177	
178	    /**
179	     * The owner's locality: the region component of its {@link #customerCode}
180	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
181	     * is assigned. The region was derived from the owner's postcode and city when
182	     * the identity was minted, so the locality now follows the identity rather than
183	     * being recomputed from the current city and postcode.
184	     */
185	    public String getLocality() {
186	        return CustomerCode.regionOf(this.customerCode);
187	    }
188	
189	    /**
190	     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
191	     * locality}, from the fixed region-to-timezone table (see
192	     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
193	     * no known timezone.
194	     */
195	    public String getTimezone() {
196	        return RegionTimezone.zoneFor(getLocality());
197	    }
198	
199	    public String getTelephone() {
200	        return this.telephone;
201	    }
202	
203	    public void setTelephone(String telephone) {
204	        this.telephone = telephone;
205	    }
206	
207	    public String getEmail() {
208	        return this.email;
209	    }
210	
211	    public void setEmail(String email) {
212	        this.email = email;
213	    }
214	
215	    public LocalDate getBirthDate() {
216	        return this.birthDate;
217	    }
218	
219	    public void setBirthDate(LocalDate birthDate) {
220	        this.birthDate = birthDate;
221	    }
222	
223	    /**
224	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
225	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
226	     */
227	    public AgeBand getAgeBand() {
228	        return AgeBand.on(this.birthDate, this.registrationDate);
229	    }
230	
231	    public LocalDate getRegistrationDate() {
232	        return this.registrationDate;
233	    }
234	
235	    public void setRegistrationDate(LocalDate registrationDate) {
236	        this.registrationDate = registrationDate;
237	    }
238	
239	    public String getCustomerCode() {
240	        return this.customerCode;
241	    }
242	
243	    public void setCustomerCode(String customerCode) {
244	        this.customerCode = customerCode;
245	    }
246	
247	    /**
248	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
249	     * where {@code YY} is the last two digits of the {@link #registrationDate}
250	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
251	     */
252	    public String getMembershipNumber() {
253	        if (this.customerCode == null || this.registrationDate == null) {
254	            return null;
255	        }
256	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
257	    }
258	
259	    /**
260	     * The Luhn check digit (0-9) computed over the digits of the
261	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
262	     */
263	    public Integer getCheckDigit() {
264	        if (this.customerCode == null) {
265	            return null;
266	        }
267	        return Luhn.checkDigit(this.customerCode);
268	    }
269	
270	    public String getHouseholdId() {
271	        return this.householdId;
272	    }
273	
274	    public void setHouseholdId(String householdId) {
275	        this.householdId = householdId;
276	    }
277	
278	    /**
279	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
280	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
281	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
282	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
283	     * when their whole identity keys are equal; because the telephone is part of the key, household
284	     * members with different telephones have different keys.
285	     */
286	    public String getIdentityKey() {
287	        return String.join("|",
288	            this.telephone == null ? "" : this.telephone,
289	            this.email == null ? "" : this.email,
290	            this.householdId == null ? "" : this.householdId);
291	    }
292	
293	    /** Tenure, in days, beyond which an owner earns the tenure membership points. */
294	    private static final long TENURE_DAYS_FOR_POINTS = 365;
295	
296	    /** Household size at or above which an owner earns the household membership points. */
297	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
298	
299	    /**
300	     * The owner's membership points, a score derived from the owner's own
301	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
302	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
303	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
304	     * or more, and gains {@code 3} when the owner's {@link #getTenureDays()
305	     * tenure} exceeds {@value #TENURE_DAYS_FOR_POINTS} days.
306	     */
307	    public Integer getMembershipPoints() {
308	        int points = 0;
309	        boolean hasEmail = this.email != null && !this.email.isEmpty();
310	        if (hasEmail) {
311	            points += 2;
312	        }
313	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
314	        if (noNamesakes) {
315	            points += 1;
316	        }
317	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
318	        if (largeHousehold) {
319	            points += 2;
320	        }
321	        Long tenureDays = getTenureDays();
322	        if (tenureDays != null && tenureDays > TENURE_DAYS_FOR_POINTS) {
323	            points += 3;
324	        }
325	        return points;
326	    }
327	
328	    /**
329	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
330	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
331	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
332	     */
333	    public Integer getMembershipLevel() {
334	        int points = getMembershipPoints();
335	        if (points <= 1) {
336	            return 1;
337	        }
338	        if (points <= 3) {
339	            return 2;
340	        }
341	        if (points <= 5) {
342	            return 3;
343	        }
344	        return 4;
345	    }
346	
347	    /**
348	     * The owner's tenure: the number of whole days from the {@link #registrationDate}
349	     * to the server's current date, or {@code null} when no registration date is on
350	     * file. Never negative for a registration date that is today or earlier.
351	     */
352	    public Long getTenureDays() {
353	        if (this.registrationDate == null) {
354	            return null;
355	        }
356	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
357	    }
358	
359	    /**
360	     * The owner's preferred contact channel, derived from the fields on file:
361	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
362	     */
363	    public String getContactPreference() {
364	        boolean hasEmail = this.email != null && !this.email.isEmpty();
365	        return hasEmail ? "EMAIL" : "PHONE";
366	    }
367	
368	    public Integer getNamesakeCount() {
369	        return this.namesakeCount;
370	    }
371	
372	    public void setNamesakeCount(Integer namesakeCount) {
373	        this.namesakeCount = namesakeCount;
374	    }
375	
376	    public Integer getHouseholdSize() {
377	        return this.householdSize;
378	    }
379	
380	    public void setHouseholdSize(Integer householdSize) {
381	        this.householdSize = householdSize;
382	    }
383	
384	    /**
385	     * Whether this owner, while not a declared household member, shares an existing owner's
386	     * last name and postcode but carries a different telephone. Determined once,
387	     * when the owner is created. A declared household member is never a suspected duplicate.
388	     */
389	    public Boolean getPossibleDuplicate() {
390	        return this.possibleDuplicate;
391	    }
392	
393	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
394	        this.possibleDuplicate = possibleDuplicate;
395	    }
396	
397	    /**
398	     * Whether this owner was knowingly created into a shared household. Such a declared member
399	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
400	     */
401	    public boolean isDeclaredHouseholdMember() {
402	        return this.declaredHouseholdMember;
403	    }
404	
405	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
406	        this.declaredHouseholdMember = declaredHouseholdMember;
407	    }
408	
409	    /**
410	     * The id of the existing owner this owner possibly duplicates, or {@code null}
411	     * when it has no such match.
412	     */
413	    public Integer getPossibleDuplicateOf() {
414	        return this.possibleDuplicateOf;
415	    }
416	
417	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
418	        this.possibleDuplicateOf = possibleDuplicateOf;
419	    }
420	
421	    /**
422	     * Whether this owner has been soft-deleted: {@code DELETE /api/owners/{id}} flags the owner
423	     * deleted and retains the row rather than removing it. A soft-deleted owner is still returned by
424	     * a read, but is ignored by the create endpoint's duplicate and identity checks. A newly created
425	     * owner is not deleted.
426	     */
427	    public boolean isDeleted() {
428	        return this.deleted;
429	    }
430	
431	    public void setDeleted(boolean deleted) {
432	        this.deleted = deleted;
433	    }
434	
435	    protected Set<Pet> getPetsInternal() {
436	        if (this.pets == null) {
437	            this.pets = new HashSet<>();
438	        }
439	        return this.pets;
440	    }
441	
442	    protected void setPetsInternal(Set<Pet> pets) {
443	        this.pets = pets;
444	    }
445	
446	    public List<Pet> getPets() {
447	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
448	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
449	        return Collections.unmodifiableList(sortedPets);
450	    }
451	
452	    public void setPets(List<Pet> pets) {
453	        this.pets = new HashSet<>(pets);
454	    }
455	
456	    public void addPet(Pet pet) {
457	        getPetsInternal().add(pet);
458	        pet.setOwner(this);
459	    }
460	
461	    /**
462	     * Return the Pet with the given name, or null if none found for this Owner.
463	     *
464	     * @param name to test
465	     * @return true if pet name is already in use
466	     */
467	    public Pet getPet(String name) {
468	        return getPet(name, false);
469	    }
470	
471	    /**
472	     * Return the Pet with the given name, or null if none found for this Owner.
473	     *
474	     * @param name to test
475	     * @return true if pet name is already in use
476	     */
477	    public Pet getPet(String name, boolean ignoreNew) {
478	        name = name.toLowerCase();
479	        for (Pet pet : getPetsInternal()) {
480	            if (!ignoreNew || !pet.isNew()) {
481	                String compName = pet.getName();
482	                compName = compName.toLowerCase();
483	                if (compName.equals(name)) {
484	                    return pet;
485	                }
486	            }
487	        }
488	        return null;
489	    }
490	
491	    public Pet getPet(Integer petId) {
492	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
493	    }
494	
495	    @Override
496	    public String toString() {
497	        return new ToStringCreator(this)
498	
499	            .append("id", this.getId())
500	            .append("new", this.isNew())
501	            .append("lastName", this.getLastName())
502	            .append("firstName", this.getFirstName())
503	            .append("address", this.address)
504	            .append("city", this.city)
505	            .append("telephone", this.telephone)
506	            .append("email", this.email)
507	            .toString();
508	    }
509	}
