        return this.title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    /**
     * The owner's salutation: the {@link #title} followed by a space and the
     * {@linkplain #getLastName() last name} (e.g. {@code "DR Who"}), or just the
     * last name when no title is on file.
     */
    public String getSalutation() {
        if (this.title == null || this.title.isEmpty()) {
            return getLastName();
        }
        return this.title + " " + getLastName();
    }

    public String getAddress() {
        return this.address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getAddressLine1() {
        return this.addressLine1;
    }

    public void setAddressLine1(String addressLine1) {
        this.addressLine1 = addressLine1;
    }

    public String getAddressLine2() {
        return this.addressLine2;
    }

    public void setAddressLine2(String addressLine2) {
        this.addressLine2 = addressLine2;
    }

    public String getCity() {
        return this.city;
    }

    public void setCity(String city) {
        this.city = city;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    /**
     * The owner's locality: the region component of its {@link #customerCode}
     * identity (see {@link CustomerCode}), or {@code null} when no customer code
     * is assigned. The region was derived from the owner's postcode and city when
     * the identity was minted, so the locality now follows the identity rather than
     * being recomputed from the current city and postcode.
     */
    public String getLocality() {
        return CustomerCode.regionOf(this.customerCode);
    }

    /**
     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
     * locality}, from the fixed region-to-timezone table (see
     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
     * no known timezone.
     */
    public String getTimezone() {
        return RegionTimezone.zoneFor(getLocality());
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    /**
     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
     */
    public AgeBand getAgeBand() {
        return AgeBand.on(this.birthDate, this.registrationDate);
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    /**
     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
     * where {@code YY} is the last two digits of the {@link #registrationDate}
     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
     */
    public String getMembershipNumber() {
        if (this.customerCode == null || this.registrationDate == null) {
            return null;
        }
        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
    }

    /**
     * The Luhn check digit (0-9) computed over the digits of the
     * {@link #customerCode}, or {@code null} when no customer code is assigned.
     */
